 17 package org.gradle.launcher.daemon.client;
 18 
 19 import org.gradle.api.GradleException;
 20 import org.gradle.api.internal.specs.ExplainingSpec;
 21 import org.gradle.api.logging.Logger;
 22 import org.gradle.api.logging.Logging;
 23 import org.gradle.internal.id.IdGenerator;
 24 import org.gradle.internal.time.CountdownTimer;
 25 import org.gradle.internal.time.Time;
 26 import org.gradle.launcher.daemon.context.DaemonConnectDetails;
 27 import org.gradle.launcher.daemon.context.DaemonContext;
 28 import org.gradle.launcher.daemon.logging.DaemonMessages;
 29 import org.gradle.launcher.daemon.protocol.Stop;
 30 import org.gradle.launcher.daemon.protocol.StopWhenIdle;
 31 
 32 import java.util.Collection;
 33 import java.util.HashSet;
 34 import java.util.Set;
 35 import java.util.UUID;
 36 import java.util.concurrent.TimeUnit;
 37 
 38 /**
 39  * <p>To stop a daemon:</p>
 40  *
 41  * <ul>
 42  * <li>The client creates a connection to daemon.</li>
 43  * <li>The client sends exactly one {@link org.gradle.launcher.daemon.protocol.Stop} message.</li>
 44  * <li>The daemon sends exactly one {@link org.gradle.launcher.daemon.protocol.Result} message. It may no longer send any messages.</li>
 45  * <li>The client sends a {@link org.gradle.launcher.daemon.protocol.Finished} message once it has received the {@link org.gradle.launcher.daemon.protocol.Result} message.
 46  *     It may no longer send any messages.</li>
 47  * <li>The client closes the connection.</li>
 48  * <li>The daemon closes the connection once it has received the {@link org.gradle.launcher.daemon.protocol.Finished} message.</li>
 49  * </ul>
 50  */
 51 public class DaemonStopClient {
 52     private static final Logger LOGGER = Logging.getLogger(DaemonClient.class);
 53     private static final int STOP_TIMEOUT_SECONDS = 30;
 54     private final DaemonConnector connector;
 55     private final IdGenerator<UUID> idGenerator;
 56     private final StopDispatcher stopDispatcher;
 57 
 58     public DaemonStopClient(DaemonConnector connector, IdGenerator<UUID> idGenerator) {
 59         this.connector = connector;
 60         this.idGenerator = idGenerator;
 61         this.stopDispatcher = new StopDispatcher();
 62     }
 63 
 64     /**
 65      * Requests that the given daemons stop when idle. Does not block and returns before the daemons have all stopped.
 66      */
 67     public void gracefulStop(Collection<DaemonConnectDetails> daemons) {
 68         for (DaemonConnectDetails daemon : daemons) {
 69             DaemonClientConnection connection = connector.maybeConnect(daemon);
 70             if (connection == null) {
 71                 continue;
 72             }
 73             try {
 74                 LOGGER.debug("Requesting daemon {} stop when idle", daemon);
 75                 stopDispatcher.dispatch(connection, new StopWhenIdle(idGenerator.generateId(), connection.getDaemon().getToken()));
 76                 LOGGER.lifecycle("Gradle daemon stopped.");
 77             } finally {
 78                 connection.stop();
 79             }
 80         }
 81     }
 82 
 83     /**
 84      * Stops all daemons, blocking until all have completed.
 85      */
 86     public void stop() {
 87         CountdownTimer timer = Time.startCountdownTimer(STOP_TIMEOUT_SECONDS, TimeUnit.SECONDS);
 88         final Set<String> seen = new HashSet<String>();
 89 
 90         ExplainingSpec<DaemonContext> spec = new ExplainingSpec<DaemonContext>() {
 91             @Override
 92             public String whyUnsatisfied(DaemonContext element) {
 93                 return "already seen";
 94             }
 95 
 96             @Override
 97             public boolean isSatisfiedBy(DaemonContext element) {
 98                 return !seen.contains(element.getUid());
 99             }
100         };
101 
102         DaemonClientConnection connection = connector.maybeConnect(spec);
103         if (connection == null) {
104             LOGGER.lifecycle(DaemonMessages.NO_DAEMONS_RUNNING);
105             return;
106         }
107 
108         LOGGER.lifecycle("Stopping Daemon(s)");
109 
110         //iterate and stop all daemons
111         int numStopped = 0;
112         while (connection != null && !timer.hasExpired()) {
113             try {
114                 seen.add(connection.getDaemon().getUid());
115                 LOGGER.debug("Requesting daemon {} stop now", connection.getDaemon());
116                 boolean stopped = stopDispatcher.dispatch(connection, new Stop(idGenerator.generateId(), connection.getDaemon().getToken()));
117                 if (stopped) {
118                     numStopped++;
119                 }
120             } finally {
121                 connection.stop();
122             }
123             connection = connector.maybeConnect(spec);
124         }
125 
126         if (numStopped > 0) {
127             LOGGER.lifecycle(numStopped + " Daemon" + ((numStopped > 1) ? "s" : "") + " stopped");
128         }
129 
130         if (connection != null) {
131             throw new GradleException(String.format("Timeout waiting for all daemons to stop. Waited %s.", timer.getElapsed()));
132         }
133     }
134 }
